package com.zenbyte.leave.controller;
import com.zenbyte.leave.dto.AttendanceUpdateRequest; import com.zenbyte.leave.service.AttendanceService; import jakarta.validation.Valid; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/admin/attendance") public class AttendanceController {private final AttendanceService s;public AttendanceController(AttendanceService s){this.s=s;} @GetMapping public List<Map<String,Object>> list(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date){return s.forDate(date);} @PutMapping public void update(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date,@Valid @RequestBody List<AttendanceUpdateRequest> updates){s.update(date,updates);} @PostMapping("/mark-all-present") public void all(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date){s.markAllPresent(date);} }
